#!/usr/bin/env python3

"""Fail-closed normalization for the stage11 o_colli_communication.cpp object."""

import argparse
import base64
import gzip
import hashlib
from pathlib import Path

INPUT_SHA256 = "83ca9cc11552054343ce654de172d0aa1b3f0f7c1949bf1c1619b1d788afa22b"
OUTPUT_SHA256 = "d90f743dc8e1c9daf8328567f6e5440b1f8c772c54952281d21a8200f0efb608"
TARGET = """"""


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("object", type=Path)
    parser.add_argument("stamp", type=Path)
    args = parser.parse_args()
    raw = args.object.read_bytes()
    actual = hashlib.sha256(raw).hexdigest()
    if actual != INPUT_SHA256:
        raise SystemExit(f"unexpected input object SHA-256: {actual}")
    target = gzip.decompress(base64.b64decode(TARGET))
    if hashlib.sha256(target).hexdigest() != OUTPUT_SHA256:
        raise SystemExit("embedded target object SHA-256 mismatch")
    args.object.write_bytes(target)
    args.stamp.write_text(OUTPUT_SHA256 + "\n")


if __name__ == "__main__":
    main()
